// ADO PR-merged payload -> Teams AdaptiveCard (v1.4).
// Power Automate 'Post card in a chat or channel' action requires the
// WHOLE request body to be a valid AdaptiveCard with type='AdaptiveCard'.
// Container.style drives the color band (dev=accent blue, main=warning yellow).
const evt = ($input.first().json.body) || {};
const r = evt.resource || {};
const target = (r.targetRefName || '').replace('refs/heads/', '');
const source = (r.sourceRefName || '').replace('refs/heads/', '');
const repo = r.repository && r.repository.name || 'unknown';
const title = r.title || '(no title)';
const author = (r.createdBy && (r.createdBy.displayName || r.createdBy.uniqueName)) || 'unknown';
const prId = r.pullRequestId || 0;
const prUrl = (r._links && r._links.web && r._links.web.href)
              || `https://dev.azure.com/${evt.publisherId || 'trustworks'}/App/_git/${repo}/pullrequest/${prId}`;

if (target !== 'dev' && target !== 'main') {
  return [{ json: { _skip: true, reason: `target ${target} is not dev/main` } }];
}

const styleMap = { dev: 'accent', main: 'warning' };
const label    = target === 'main' ? 'PROD merge (release cut)' : 'DEV merge';

return [{ json: {
  _skip: false,
  card: {
    type: 'AdaptiveCard',
    '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
    version: '1.4',
    body: [
      {
        type: 'Container',
        style: styleMap[target],
        bleed: true,
        items: [
          { type: 'TextBlock', text: label, weight: 'Bolder', size: 'Medium', wrap: true },
          { type: 'TextBlock', text: title, weight: 'Bolder', wrap: true, spacing: 'Small' },
          { type: 'TextBlock', text: `${repo} - ${source} → ${target}`, isSubtle: true, wrap: true, spacing: 'None' }
        ]
      },
      {
        type: 'FactSet',
        facts: [
          { title: 'PR:',     value: `#${prId}` },
          { title: 'Author:', value: author },
          { title: 'Repo:',   value: repo }
        ]
      }
    ],
    actions: [
      { type: 'Action.OpenUrl', title: 'Open PR', url: prUrl }
    ]
  }
}}];

// ADO pipeline run-state-changed -> Teams AdaptiveCard.
// Container.style: good = green (succeeded), attention = red (failed).
const evt = ($input.first().json.body) || {};
const r = evt.resource || {};
const run = r.run || r;
const state = run.state || r.state;
const result = run.result || r.result;
const pipeline = (r.pipeline && r.pipeline.name) || (run.pipeline && run.pipeline.name) || 'unknown';
const runId = run.id || r.id || 0;
const runUrl = (run._links && run._links.web && run._links.web.href)
               || (r._links && r._links.web && r._links.web.href)
               || `https://dev.azure.com/trustworks/App/_build/results?buildId=${runId}`;

if (state !== 'completed') {
  return [{ json: { _skip: true, reason: `state=${state}, only notifying on completed` } }];
}

const ok = result === 'succeeded';
const style = ok ? 'good' : 'attention';
const label = ok ? 'Pipeline succeeded' : `Pipeline ${result || 'failed'}`;

return [{ json: {
  _skip: false,
  card: {
    type: 'AdaptiveCard',
    '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
    version: '1.4',
    body: [
      {
        type: 'Container',
        style,
        bleed: true,
        items: [
          { type: 'TextBlock', text: label, weight: 'Bolder', size: 'Medium', wrap: true },
          { type: 'TextBlock', text: pipeline, weight: 'Bolder', wrap: true, spacing: 'Small' },
          { type: 'TextBlock', text: `Run #${runId} - ${result || state}`, isSubtle: true, wrap: true, spacing: 'None' }
        ]
      },
      {
        type: 'FactSet',
        facts: [
          { title: 'Pipeline:', value: pipeline },
          { title: 'Run:',      value: `#${runId}` },
          { title: 'Result:',   value: result || state }
        ]
      }
    ],
    actions: [
      { type: 'Action.OpenUrl', title: 'Open run', url: runUrl }
    ]
  }
}}];
